import {readFile} from 'node:fs/promises';
import {earthFixture} from './earth-fixture.mjs';
export const MELEE_SKILL={kind:'melee',windupTicks:2,recoveryTicks:5,cooldownTicks:50,rangeX:500000,rangeY:500000,speed:1000,coefficient:{n:'1',d:'100'},staggerTicks:3};
export async function monsterFixture(patch={}){const release=JSON.parse(await readFile(new URL('../../../shared/fixtures/warrior-first-normal.test.json',import.meta.url),'utf8'));const monsters={version:'local-melee-v1',decisionTicks:5,control:{staggerTicks:3,knockback:100},templates:Object.fromEntries(release.nodes.filter(n=>n.kind==='monster').map(n=>[`${n.id}@${n.version}`,{type:'humanoid',skillRef:'slash',behavior:'chase',rewardTag:'none',resist:{bleed:false,stagger:false,knockback:false,knockdown:false}}])),skills:{slash:{...MELEE_SKILL}},...patch};return earthFixture({schemaVersion:6,profile:'local-test-monsters',capabilities:['basic','cross','bengshan','badao','earth','monsters','no-rewards'],monsters});}
